/* Deleting a community members still pay for, and a new admin's setup list (round 33), run after part 81. Three server only tables. `community_deletions`, one row per community whose deletion is scheduled: how (at the end of what members paid for, or now with refunds), when it is deleted, who asked, what the community was before (so Undo brings it back as it was), and whether it was completed or undone. `community_deletion_members`, one row per paid membership the deletion stopped: its subscription, when its paid time ends, whether the member had already cancelled, and, for a deletion now, the payment refunded and the Stripe refund (so a retry never refunds twice), with when the member was emailed and, after an Undo, when the membership was resumed. `community_setup_progress`, what each owner or admin skipped or finished by hand on the setup list (the intro video watched, the app installed, a step skipped, the list hidden). One index finds the deletions that are due for the community job run. No existing row changes. Until it runs, a community nobody pays for is still deleted at once, a paid one says this part is needed, and the setup list works without skips. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_deletions (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, state text NOT NULL DEFAULT 'scheduled', mode text NOT NULL, delete_at timestamptz NOT NULL, requested_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, requested_at timestamptz NOT NULL DEFAULT now(), prior_status text NOT NULL, prior_archived_at timestamptz, members_total integer NOT NULL DEFAULT 0, undone_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, undone_at timestamptz, completed_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_deletions_pkey PRIMARY KEY (community_id), CONSTRAINT community_deletions_state_check CHECK (state IN ('scheduled', 'completed', 'undone')), CONSTRAINT community_deletions_mode_check CHECK (mode IN ('period_end', 'now')), CONSTRAINT community_deletions_error_check CHECK (last_error IS NULL OR char_length(last_error) <= 500));
CREATE INDEX IF NOT EXISTS community_deletions_due_idx ON public.community_deletions (delete_at) WHERE state = 'scheduled';
ALTER TABLE public.community_deletions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_deletions FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_deletions TO service_role;
CREATE TABLE IF NOT EXISTS public.community_deletion_members (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, membership_id uuid NOT NULL, stripe_subscription_id text, buyer_id uuid, buyer_email text, mode text NOT NULL, period_end timestamptz, was_cancelling boolean NOT NULL DEFAULT false, cancelled_at timestamptz, refund_order_id uuid, refund_cents integer, stripe_refund_id text, refunded_at timestamptz, emailed_at timestamptz, resumed_at timestamptz, attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_deletion_members_pkey PRIMARY KEY (community_id, membership_id), CONSTRAINT community_deletion_members_mode_check CHECK (mode IN ('period_end', 'now')), CONSTRAINT community_deletion_members_refund_check CHECK (refund_cents IS NULL OR refund_cents >= 0), CONSTRAINT community_deletion_members_error_check CHECK (error IS NULL OR char_length(error) <= 500));
ALTER TABLE public.community_deletion_members ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_deletion_members FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_deletion_members TO service_role;
CREATE TABLE IF NOT EXISTS public.community_setup_progress (community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, step text NOT NULL, done_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_setup_progress_pkey PRIMARY KEY (community_id, user_id, step), CONSTRAINT community_setup_progress_step_check CHECK (char_length(step) BETWEEN 1 AND 40));
ALTER TABLE public.community_setup_progress ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_setup_progress FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_setup_progress TO service_role;
notify pgrst, 'reload schema';
